// New York City's outline, simplified, for the map: where it may go, and whether the map center
// is inside the five boroughs. The server checks the full-detail boundaries; this only decides
// whether to offer "Search this area". Generated by scripts/load_places.py from NYC Open Data.
import outline from './nyc-outline.json'

type Ring = number[][]
type Polygon = Ring[]

const polygons: Polygon[] = outline.type === 'MultiPolygon'
  ? (outline.coordinates as unknown as Polygon[])
  : [outline.coordinates as unknown as Polygon]

const xs = polygons.flatMap((p) => p[0].map((pt) => pt[0]))
const ys = polygons.flatMap((p) => p[0].map((pt) => pt[1]))

// [[south, west], [north, east]] with a little room, so the edge of the city is not on the edge.
export const NYC_BOUNDS: [[number, number], [number, number]] = [
  [Math.min(...ys) - 0.03, Math.min(...xs) - 0.05],
  [Math.max(...ys) + 0.03, Math.max(...xs) + 0.05],
]

function inRing(ring: Ring, lng: number, lat: number): boolean {
  let inside = false
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i]
    const [xj, yj] = ring[j]
    if (yi > lat !== yj > lat && lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside
  }
  return inside
}

export function insideNyc(lat: number, lng: number): boolean {
  return polygons.some(([outer, ...holes]) => inRing(outer, lng, lat) && !holes.some((h) => inRing(h, lng, lat)))
}
